const STORAGE_KEY = 'minghui-learning-state';
const LEGACY_STORAGE_KEY = 'qiming-learning-state';
const BRAND_NAME = '铭惠学习';
const AI_BRAND_NAME = '铭惠 AI';
const USER_NAME = '小妹';
const USER_INITIAL = '妹';
// 这是资料结构版本，不是每次发版都要递增的应用版本。
// 只有没有保存资料的首次安装，或旧版演示资料，才初始化为新用户；后续 APK 升级永远沿用已有记录。
const PROFILE_SCHEMA_VERSION = 2;

let state = loadState();

function loadState() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY) || localStorage.getItem(LEGACY_STORAGE_KEY);
    const saved = stored ? JSON.parse(stored) : null;
    const hasSavedProfile = Boolean(saved && typeof saved === 'object' && !Array.isArray(saved));
    const isLegacyDemoProfile = hasSavedProfile && !Object.prototype.hasOwnProperty.call(saved, 'profileVersion');
    const shouldInitializeNewProfile = !hasSavedProfile || isLegacyDemoProfile;
    if (shouldInitializeNewProfile) localStorage.removeItem('minghui-analytics-user-id');
    const nextState = { ...defaultState, ...(shouldInitializeNewProfile ? {} : saved), profileVersion: PROFILE_SCHEMA_VERSION, page: 'home', toast: '', selectedAnswer: null, questionAnswered: false, aiImageData: null, aiImageName: '' };
    if (!nextState.practiceSetBySubject || typeof nextState.practiceSetBySubject !== 'object' || Array.isArray(nextState.practiceSetBySubject)) nextState.practiceSetBySubject = {};
    if (!nextState.completedPracticeSets || typeof nextState.completedPracticeSets !== 'object' || Array.isArray(nextState.completedPracticeSets)) nextState.completedPracticeSets = {};
    if (!nextState.diagnosticAnswers || typeof nextState.diagnosticAnswers !== 'object' || Array.isArray(nextState.diagnosticAnswers)) nextState.diagnosticAnswers = {};
    if (!nextState.diagnosticCompleted || typeof nextState.diagnosticCompleted !== 'object' || Array.isArray(nextState.diagnosticCompleted)) nextState.diagnosticCompleted = {};
    if (!nextState.diagnosticResults || typeof nextState.diagnosticResults !== 'object' || Array.isArray(nextState.diagnosticResults)) nextState.diagnosticResults = {};
    if (!Array.isArray(nextState.aiConversation)) nextState.aiConversation = [];
    if (typeof nextState.aiQuestion !== 'string' || /<\/?\s*(textarea|div|section|button)\b/i.test(nextState.aiQuestion)) nextState.aiQuestion = '';
    return nextState;
  } catch {
    return { ...defaultState };
  }
}

function saveState() {
  const { toast, aiImageData, aiImageName, ...persisted } = state;
  localStorage.setItem(STORAGE_KEY, JSON.stringify(persisted));
}

function getAnalyticsUserId() {
  const storageKey = 'minghui-analytics-user-id';
  const existing = localStorage.getItem(storageKey);
  if (existing) return existing;
  const generated = globalThis.crypto?.randomUUID?.() || `anon-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  localStorage.setItem(storageKey, generated);
  return generated;
}

const ONLINE_API_ORIGIN = 'https://zheng-production-440f.up.railway.app';

function apiEndpoint(pathname) {
  const nativeAssetPage = globalThis.location?.hostname === 'appassets.androidplatform.net';
  const origin = globalThis.MINGHUI_API_ORIGIN || (nativeAssetPage ? ONLINE_API_ORIGIN : '');
  return `${origin}${pathname}`;
}

function trackEvent(eventName, metadata = {}) {
  if (!eventName) return;
  const safeMetadata = Object.fromEntries(
    Object.entries(metadata)
      .filter(([, value]) => ['string', 'number', 'boolean'].includes(typeof value))
      .slice(0, 8),
  );
  const payload = {
    userId: getAnalyticsUserId(),
    eventName,
    page: state.page,
    subjectId: state.selectedSubject,
    grade: state.grade,
    semester: state.semester,
    textbook: state.textbook,
    metadata: safeMetadata,
  };
  if (globalThis.AndroidBridge?.recordEvent) {
    try { globalThis.AndroidBridge.recordEvent(JSON.stringify(payload)); } catch {}
    return;
  }
  fetch(apiEndpoint('/api/events'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
    keepalive: true,
  }).catch(() => {});
}

