function getSubject(id = state.selectedSubject) {
  return subjects.find((item) => item.id === id) || subjects[1];
}

function subjectIdFromName(name = '') {
  const normalized = String(name).replace('道德与法治', '道法');
  return subjects.find((subject) => normalized.includes(subject.name) || subject.name.includes(normalized))?.id || state.selectedSubject;
}

function getPracticeSetNumber(subjectId = state.selectedSubject) {
  return Math.max(1, Number(state.practiceSetBySubject?.[subjectId] || 1));
}

function getCompletedPracticeSets(subjectId = state.selectedSubject) {
  return Math.max(0, Number(state.completedPracticeSets?.[subjectId] || 0));
}

function getPracticeQuestions(subjectId = state.selectedSubject, setNumber = getPracticeSetNumber(subjectId)) {
  const matched = questions.filter((question) => question.subjectId === subjectId);
  const bank = matched.length ? matched : questions.filter((question) => question.subjectId === 'math');
  const count = Math.min(10, bank.length);
  const offset = ((Math.max(1, setNumber) - 1) * 7) % bank.length;
  const selected = Array.from({ length: count }, (_, index) => bank[(offset + index) % bank.length]);
  return setNumber % 2 === 0 ? selected.reverse() : selected;
}

function getSubjectBankCount(subjectId = state.selectedSubject) {
  return questions.filter((question) => question.subjectId === subjectId).length;
}

function getSelfTestQuestions(subjectId = state.selfTestSubject || state.selectedSubject) {
  const matched = questions.filter((question) => question.subjectId === subjectId);
  const bank = matched.length ? matched : questions.filter((question) => question.subjectId === 'math');
  return bank.slice(0, 3);
}

