function homeFoundationCard() {
  const data = reportData();
  const weakest = [...data.rows].sort((a, b) => a.mastery - b.mastery)[0];
  const completed = data.completedDiagnostics;
  return `<section class="content-card home-foundation-card"><div class="home-foundation-copy"><span class="card-eyebrow">FOUNDATION FIRST</span><h3>${completed ? `已完成 ${completed} 科诊断，继续补最薄弱的一科` : '先做5分钟基础诊断，系统才知道从哪里教起'}</h3><p>${completed ? `当前最建议先补：${weakest.name} · ${weakest.route}` : '每科5道基础题，不排名、不扣分，只帮你找到下一小步。'}</p></div><div class="home-foundation-meta"><strong>${completed ? `${weakest.mastery}%` : '5 min'}</strong><span>${completed ? '当前最低掌握度' : '完成一科基础定位'}</span></div><button class="primary-button" data-page="diagnostic">${completed ? '继续诊断' : '开始诊断'} ${icon('arrow', 15)}</button></section>`;
}

function augmentAiPage() {
  if (state.aiLoading || !state.aiResult) return;
  const answerHighlight = document.querySelector('.answer-highlight');
  if (!answerHighlight) return;
  const approachSection = document.querySelector('.approaches-section');
  const approachList = approachSection?.querySelector('.approach-list');
  if (approachList && approachList.querySelectorAll('.approach-card').length > 0 && approachList.querySelectorAll('.approach-card').length < 3) {
    const fallbackApproach = document.createElement('article');
    fallbackApproach.className = 'approach-card';
    fallbackApproach.innerHTML = `<span>3</span><div><strong>方法三 · 回代验证</strong><p>把得到的答案代回原题，检查条件、单位和结果是否与题目一致。</p><small>做完题后的快速自检</small></div>`;
    approachList.appendChild(fallbackApproach);
  }
  const approachTitle = approachSection?.querySelector('.ai-section-title strong');
  const approachCount = approachSection?.querySelectorAll('.approach-card').length || 0;
  if (approachTitle && approachCount) approachTitle.textContent = `不同解题思路（${approachCount}套）`;
  const inputHint = document.querySelector('.ai-input-foot > span');
  if (inputHint) inputHint.textContent = '支持文字、图片；将返回答案、步骤和 3 套解题思路';
  const answer = answerHighlight.querySelector('strong');
  if (answer && state.aiHintLevel < 3) {
    answer.textContent = '先自己试一试，再查看答案';
    answer.classList.add('answer-hidden');
  }
  const hintText = state.aiHintLevel >= 2
    ? (state.aiResult.steps || []).slice(0, state.aiHintLevel === 2 ? 2 : 3).join(' → ')
    : state.aiHintLevel === 1
      ? '先圈出题目给出的已知条件，再想想它对应哪个定义或公式。'
      : '先不看答案：这道题最重要的关键词是什么？你能先说出第一步吗？';
  const hintPanel = document.createElement('div');
  hintPanel.className = 'ai-hint-panel';
  hintPanel.innerHTML = `<div class="ai-hint-head"><span>${icon('spark', 14)}</span><strong>分层提示</strong><small>${state.aiHintLevel >= 3 ? '已展开完整答案' : '先提示，再自己完成'}</small></div><p>${escapeHtml(hintText)}</p><div class="ai-hint-actions"><button class="secondary-button ${state.aiHintLevel === 1 ? 'active' : ''}" data-action="ai-hint" data-level="1">给我一个提示</button><button class="secondary-button ${state.aiHintLevel === 2 ? 'active' : ''}" data-action="ai-hint" data-level="2">再提示一步</button><button class="primary-button" data-action="ai-hint" data-level="3">查看答案 ${icon('arrow', 13)}</button></div></div>`;
  answerHighlight.insertAdjacentElement('afterend', hintPanel);
  if (state.aiImageData && !document.querySelector('.ocr-confirm-note')) {
    const recognized = document.querySelector('.recognized-question');
    if (recognized) recognized.insertAdjacentHTML('afterend', `<div class="ocr-confirm-note">${icon('spark', 13)} 图片识别结果仅供确认；如果文字、符号或图形不准确，请回到左侧输入框修改后再解题。</div>`);
  }
}

function augmentLearnPage() {
  const subject = getSubject();
  const filterBar = document.querySelector('.filter-bar');
  if (filterBar) filterBar.insertAdjacentHTML('afterend', `<div class="content-sync-note">${icon('book', 14)} <span><strong>${escapeHtml(state.grade)} · ${escapeHtml(state.semester)} · ${escapeHtml(state.textbook)}</strong><small>${escapeHtml(textbookNote(subject))}</small></span><button class="text-button" data-action="refresh-content">更新匹配 ${icon('arrow', 13)}</button></div>`);
  const library = document.querySelector('.subject-library');
  if (library) library.insertAdjacentHTML('afterend', subjectTools(subject));
}

function augmentWrongPage() {
  const wrongQuestions = questions.filter((question) => state.wrongIds.includes(question.id));
  const subjectFilteredQuestions = state.wrongSubjectFilter === 'all' ? wrongQuestions : wrongQuestions.filter((question) => question.subjectId === state.wrongSubjectFilter);
  const tabGroup = document.querySelector('.tab-group');
  if (tabGroup) {
    const filters = [['all', '全部', subjectFilteredQuestions.length], ['concept', '概念混淆', subjectFilteredQuestions.filter((question) => errorReasonForQuestion(question) === '概念混淆').length], ['method', '方法不会', subjectFilteredQuestions.filter((question) => errorReasonForQuestion(question) === '方法不会').length], ['reading', '审题遗漏', subjectFilteredQuestions.filter((question) => errorReasonForQuestion(question) === '审题遗漏').length]];
    tabGroup.innerHTML = filters.map(([id, label, count]) => `<button class="${state.wrongFilter === id ? 'active' : ''}" data-action="filter-wrong" data-filter="${id}">${label} <span>${count}</span></button>`).join('');
  }
  const subjectToolbar = document.querySelector('.wrong-toolbar');
  if (subjectToolbar) {
    const filterButton = subjectToolbar.querySelector('.filter-button');
    if (filterButton) filterButton.innerHTML = `${icon('target', 16)} 科目分类 ${icon('chevron', 14)}`;
    if (!document.querySelector('.wrong-subject-tabs')) {
      const subjectButtons = subjects.map((subject) => {
        const count = wrongQuestions.filter((question) => question.subjectId === subject.id).length;
        return `<button class="wrong-subject-tab ${state.wrongSubjectFilter === subject.id ? 'active' : ''}" data-action="filter-wrong-subject" data-wrong-subject="${subject.id}"><span class="subject-symbol ${subject.tone}">${subject.icon}</span><span>${subject.name}</span><small>${count}</small></button>`;
      }).join('');
      subjectToolbar.insertAdjacentHTML('afterend', `<div class="wrong-subject-tabs"><span class="wrong-subject-heading">按学科分类</span><div class="wrong-subject-list"><button class="wrong-subject-tab ${state.wrongSubjectFilter === 'all' ? 'active' : ''}" data-action="filter-wrong-subject" data-wrong-subject="all"><span class="subject-symbol blue">全</span><span>全部</span><small>${wrongQuestions.length}</small></button>${subjectButtons}</div></div>`);
    }
  }
  document.querySelectorAll('.wrong-item').forEach((item, index) => {
    const question = wrongQuestions[index];
    const reason = errorReasonForQuestion(question);
    item.dataset.errorReason = reason;
    const reasonLabel = item.querySelector('.error-type');
    if (reasonLabel) reasonLabel.textContent = reason;
    const answerLabel = item.querySelectorAll('.wrong-answer b')[1];
    if (answerLabel) answerLabel.textContent = questionAnswerLabel(question);
    const filterMap = { concept: '概念混淆', method: '方法不会', reading: '审题遗漏' };
    const subjectMatched = state.wrongSubjectFilter === 'all' || question.subjectId === state.wrongSubjectFilter;
    const reasonMatched = state.wrongFilter === 'all' || reason === filterMap[state.wrongFilter];
    item.hidden = !(subjectMatched && reasonMatched);
  });
  const toolbar = document.querySelector('.wrong-toolbar');
  const subjectTabs = document.querySelector('.wrong-subject-tabs');
  const visibleCount = subjectFilteredQuestions.filter((question) => state.wrongFilter === 'all' || errorReasonForQuestion(question) === ({ concept: '概念混淆', method: '方法不会', reading: '审题遗漏' }[state.wrongFilter])).length;
  const countLabel = document.querySelector('.page-heading .title-count');
  if (countLabel) countLabel.textContent = `${state.wrongSubjectFilter === 'all' ? wrongQuestions.length : visibleCount} 道待复习`;
  const reviewNoteAnchor = subjectTabs || toolbar;
  if (reviewNoteAnchor && !document.querySelector('.wrong-review-note')) reviewNoteAnchor.insertAdjacentHTML('afterend', `<div class="wrong-review-note">${icon('target', 14)} <span>先按学科定位，再按错误原因复习，更容易真正改会。</span><strong>今天建议先复习 ${Math.min(2, visibleCount)} 道</strong></div>`);
}

function augmentPracticePage() {
  const practiceQuestions = getPracticeQuestions();
  const question = practiceQuestions[state.selectedQuestion % practiceQuestions.length];
  if (!question) return;
  const questionLabel = document.querySelector('.question-label');
  if (questionLabel && !document.querySelector('.question-source-badge')) {
    const sourceLabel = question.tag.includes('历年题型') ? '历年题型风格' : '基础巩固题';
    questionLabel.insertAdjacentHTML('afterend', `<span class="question-source-badge">${sourceLabel} · 从本学科题库抽取</span>`);
  }
  if (!['fill', 'short'].includes(question.type)) return;
  const options = document.querySelector('.options');
  if (options) options.innerHTML = `<label class="typed-answer-label">${question.type === 'short' ? '请用关键词作答' : '请输入答案'}</label><input id="typed-answer-input" class="typed-answer-input" value="${escapeHtml(state.typedAnswer)}" placeholder="写下你的答案…" autocomplete="off"/>`;
  const submit = document.querySelector('[data-action="submit-answer"]');
  if (submit && !state.questionAnswered) {
    submit.disabled = false;
    submit.classList.remove('disabled');
  }
  const input = document.querySelector('#typed-answer-input');
  input?.addEventListener('input', (event) => {
    state.typedAnswer = event.target.value;
    saveState();
  });
}

function augmentRenderedPage() {
  if (state.page === 'home') document.querySelector('.page-content')?.insertAdjacentHTML('beforeend', homeFoundationCard());
  if (state.page === 'learn') augmentLearnPage();
  if (state.page === 'practice') augmentPracticePage();
  if (state.page === 'self-test') {
    const input = document.querySelector('#self-test-typed-input');
    input?.addEventListener('input', (event) => {
      state.typedAnswer = event.target.value;
      const submit = document.querySelector('[data-action="submit-self-test"]');
      if (submit) {
        const hasValue = Boolean(state.typedAnswer.trim());
        submit.disabled = !hasValue;
        submit.classList.toggle('disabled', !hasValue);
      }
      saveState();
    });
  }
  if (state.page === 'ai') augmentAiPage();
  if (state.page === 'wrong') augmentWrongPage();
}

function render() {
  const page = state.page === 'learn' ? learnPage() : state.page === 'practice' ? practicePage() : state.page === 'self-test' ? selfTestPage() : state.page === 'reference' ? referencePage() : state.page === 'ai' ? aiPage() : state.page === 'wrong' ? wrongPage() : state.page === 'profile' ? profilePage() : state.page === 'diagnostic' ? diagnosticPage() : state.page === 'report' ? reportPage() : homePage();
  document.querySelector('#app').innerHTML = page.replaceAll('启明学习', BRAND_NAME).replaceAll('启明 AI', AI_BRAND_NAME);
  augmentRenderedPage();
  bindEvents();
  if (state.page === 'ai' && state.aiResult?.followUpResponse) {
    const answerHighlight = document.querySelector('.answer-highlight');
    if (answerHighlight) {
      const followUpAnswer = document.createElement('div');
      followUpAnswer.className = 'followup-answer';
      const followUpHead = document.createElement('div');
      followUpHead.className = 'followup-answer-head';
      followUpHead.innerHTML = `${icon('spark', 14)}<strong>针对你的追问</strong>`;
      const followUpBody = document.createElement('p');
      followUpBody.textContent = state.aiResult.followUpResponse;
      followUpAnswer.append(followUpHead, followUpBody);
      answerHighlight.insertAdjacentElement('afterend', followUpAnswer);
    }
  }
  if (state.toast) setTimeout(() => { state.toast = ''; render(); }, 2600);
}

function showToast(message) {
  state.toast = message;
  saveState();
  render();
}

async function requestAiSolve(question, followUp = '', imageData = state.aiImageData) {
  if (!question.trim() && !imageData) return showToast('先输入一道题目或上传题目图片，我才能开始解题');
  trackEvent('ai_solve_start', { hasImage: Boolean(imageData), hasFollowUp: Boolean(followUp.trim()) });
  state.page = 'ai';
  state.aiQuestion = question;
  state.aiLoading = true;
  state.aiResult = null;
  state.aiHintLevel = 0;
  if (!followUp.trim()) state.aiConversation = [];
  saveState();
  render();
  try {
    const response = await fetch(apiEndpoint('/api/ai/solve'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ question, imageData, imageName: state.aiImageName, grade: state.grade, subject: getSubject().name, textbook: state.textbook, followUp, history: state.aiConversation.slice(-6) }),
    });
    if (!response.ok) throw new Error('AI service unavailable');
    state.aiResult = await response.json();
  } catch {
    state.aiResult = demoAiResult(question, Boolean(imageData), followUp);
  } finally {
    if (followUp.trim()) state.aiConversation = [...state.aiConversation, { role: 'student', content: followUp }, { role: 'assistant', content: state.aiResult?.followUpResponse || state.aiResult?.summary || '' }].slice(-6);
    state.aiLoading = false;
    trackEvent('ai_solve_complete', { isDemo: Boolean(state.aiResult?.isDemo), hasFollowUp: Boolean(followUp.trim()) });
    saveState();
    render();
  }
}

function bindEvents() {
  document.querySelector('[data-mode="photo"]')?.setAttribute('aria-label', '拍照识题');
  document.querySelectorAll('[data-page]').forEach((element) => element.addEventListener('click', () => {
    state.page = element.dataset.page;
    state.selectedAnswer = null;
    state.questionAnswered = false;
    trackEvent('page_view', { targetPage: state.page });
    saveState();
    render();
  }));
  document.querySelectorAll('[data-subject]').forEach((element) => element.addEventListener('click', () => {
    state.selectedSubject = element.dataset.subject;
    const available = textbookOptions[state.selectedSubject] || ['人教版'];
    if (!available.includes(state.textbook)) state.textbook = available[0];
    state.focusKnowledgePoint = '';
    state.focusCourseTitle = '';
    state.focusLessonOpen = false;
    state.activeTool = '';
    state.labStep = 0;
    state.voiceStatus = '';
    state.voiceScore = null;
    state.selectedQuestion = 0;
    state.selectedAnswer = null;
    state.questionAnswered = false;
    trackEvent('select_subject', { subjectId: state.selectedSubject });
    saveState();
    render();
  }));
  document.querySelectorAll('[data-filter]').forEach((element) => element.addEventListener('change', () => {
    state[element.dataset.filter] = element.value;
    if (element.dataset.filter === 'textbook') state.textbook = element.value;
    state.focusKnowledgePoint = '';
    state.focusCourseTitle = '';
    state.focusLessonOpen = false;
    state.activeTool = '';
    state.labStep = 0;
    state.selectedQuestion = 0;
    state.selectedAnswer = null;
    state.questionAnswered = false;
    trackEvent('change_filter', { filter: element.dataset.filter, value: element.value });
    saveState();
    render();
  }));
  document.querySelectorAll('[data-action]').forEach((element) => element.addEventListener('click', (event) => {
    const action = element.dataset.action;
    if (action === 'trigger-image-upload' && event.target.closest('[data-action="remove-ai-image"]')) return;
    if (action === 'start-self-test') {
      const subjectId = element.dataset.subject || state.selectedSubject;
      state.selectedSubject = subjectId;
      state.selfTestSubject = subjectId;
      state.selfTestIndex = 0;
      state.selfTestCorrect = 0;
      state.selfTestAnswered = false;
      state.selfTestCompleted = false;
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.page = 'self-test';
      state.activeTool = '';
      trackEvent('start_self_test', { subjectId });
      saveState();
      render();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (action === 'self-test-answer') {
      state.selectedAnswer = Number(element.dataset.answer);
      return render();
    }
    if (action === 'submit-self-test') {
      if (state.selfTestAnswered) return;
      const testQuestions = getSelfTestQuestions();
      const question = testQuestions[state.selfTestIndex];
      const correct = isAnswerCorrect(question);
      state.selfTestAnswered = true;
      if (correct) state.selfTestCorrect += 1;
      else if (!state.wrongIds.includes(question.id)) state.wrongIds.push(question.id);
      trackEvent('submit_self_test', { questionIndex: state.selfTestIndex, correct });
      saveState();
      return render();
    }
    if (action === 'next-self-test') {
      if (!state.selfTestAnswered) return showToast('先提交本题答案，再进入下一题');
      if (state.selfTestIndex >= getSelfTestQuestions().length - 1) finishSelfTest();
      else {
        state.selfTestIndex += 1;
        state.selfTestAnswered = false;
        state.selectedAnswer = null;
        state.typedAnswer = '';
      }
      saveState();
      return render();
    }
    if (action === 'skip-self-test') {
      if (state.selfTestIndex >= getSelfTestQuestions().length - 1) finishSelfTest();
      else {
        state.selfTestIndex += 1;
        state.selfTestAnswered = false;
        state.selectedAnswer = null;
        state.typedAnswer = '';
      }
      saveState();
      return render();
    }
    if (action === 'continue-practice') {
      state.selectedSubject = element.dataset.subject || state.selfTestSubject;
      state.selectedQuestion = 0;
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.questionAnswered = false;
      state.page = 'practice';
      trackEvent('start_practice', { subjectId: state.selectedSubject, source: 'self_test' });
      saveState();
      render();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (action === 'back-to-learn') {
      state.page = 'learn';
      state.activeTool = '';
      state.selectedAnswer = null;
      state.typedAnswer = '';
      saveState();
      return render();
    }
    if (action === 'answer') {
      state.selectedAnswer = Number(element.dataset.answer);
      return render();
    }
    if (action === 'submit-answer') {
      state.questionAnswered = true;
      const practiceQuestions = getPracticeQuestions();
      const question = practiceQuestions[state.selectedQuestion % practiceQuestions.length];
      const correct = isQuestionCorrect(question);
      if (correct) state.points += 10;
      else if (!state.wrongIds.includes(question.id)) state.wrongIds.push(question.id);
      trackEvent('submit_answer', { questionId: question.id, correct, setNumber: getPracticeSetNumber() });
      saveState();
      return render();
    }
    if (action === 'next-question') {
      const practiceQuestions = getPracticeQuestions();
      if (state.selectedQuestion % practiceQuestions.length >= practiceQuestions.length - 1) {
        const subjectId = state.selectedSubject;
        const completedSet = getPracticeSetNumber(subjectId);
        state.completedPracticeSets[subjectId] = Math.max(getCompletedPracticeSets(subjectId), completedSet);
        state.practiceSetBySubject[subjectId] = completedSet + 1;
        state.selectedQuestion = 0;
        state.selectedAnswer = null;
        state.typedAnswer = '';
        state.questionAnswered = false;
        state.todayProgress = Math.min(100, state.todayProgress + 8);
        state.page = 'practice';
        state.toast = `第 ${completedSet} 套完成，已开启第 ${completedSet + 1} 套，获得 30 星星！`;
        trackEvent('complete_practice_set', { subjectId, setNumber: completedSet, questionCount: practiceQuestions.length });
        saveState();
        render();
        return;
      }
      state.selectedQuestion += 1;
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.questionAnswered = false;
      saveState();
      return render();
    }
    if (action === 'skip-question') {
      state.selectedQuestion = (state.selectedQuestion + 1) % getPracticeQuestions().length;
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.questionAnswered = false;
      saveState();
      return render();
    }
    if (action === 'diagnostic-answer') {
      const subjectId = state.diagnosticSubject;
      const diagnosticQuestions = getDiagnosticQuestions(subjectId);
      if (!state.diagnosticAnswers[subjectId]) state.diagnosticAnswers[subjectId] = {};
      state.diagnosticAnswers[subjectId][state.diagnosticIndex] = Number(element.dataset.answer);
      trackEvent('submit_diagnostic_answer', { subjectId, questionIndex: state.diagnosticIndex, answer: Number(element.dataset.answer) });
      if (state.diagnosticIndex >= diagnosticQuestions.length - 1) {
        state.diagnosticCompleted[subjectId] = true;
        state.diagnosticResults[subjectId] = getDiagnosticSummary(subjectId);
        state.diagnosticIndex = 0;
        state.todayProgress = Math.min(100, state.todayProgress + 5);
        state.toast = `${getSubject(subjectId).name}基础诊断完成，已生成补救路线`;
      } else {
        state.diagnosticIndex += 1;
      }
      saveState();
      return render();
    }
    if (action === 'select-diagnostic-subject') {
      state.diagnosticSubject = element.dataset.diagnosticSubject || state.diagnosticSubject;
      state.diagnosticIndex = 0;
      state.selectedSubject = state.diagnosticSubject;
      state.activeTool = '';
      saveState();
      return render();
    }
    if (action === 'reset-diagnostic') {
      const subjectId = state.diagnosticSubject;
      delete state.diagnosticAnswers[subjectId];
      delete state.diagnosticCompleted[subjectId];
      delete state.diagnosticResults[subjectId];
      state.diagnosticIndex = 0;
      saveState();
      return render();
    }
    if (action === 'go-diagnostic-learn') {
      state.selectedSubject = element.dataset.subject || state.diagnosticSubject;
      state.diagnosticSubject = state.selectedSubject;
      const diagnosis = getDiagnosticSummary(state.selectedSubject);
      state.focusKnowledgePoint = diagnosis.weakTags[0] || `${getSubject(state.selectedSubject).name}基础起步`;
      state.focusCourseTitle = diagnosis.route === '先补基础' ? '基础概念与例题' : '薄弱知识点专项巩固';
      state.focusLessonOpen = false;
      state.activeTool = '';
      state.page = 'learn';
      saveState();
      return render();
    }
    if (action === 'go-report-subject') {
      state.selectedSubject = element.dataset.subject || state.selectedSubject;
      state.activeTool = '';
      state.page = 'learn';
      saveState();
      return render();
    }
    if (action === 'filter-wrong') {
      state.wrongFilter = element.dataset.filter || 'all';
      trackEvent('filter_wrong', { reason: state.wrongFilter });
      saveState();
      return render();
    }
    if (action === 'filter-wrong-subject') {
      state.wrongSubjectFilter = element.dataset.wrongSubject || 'all';
      state.wrongFilter = 'all';
      trackEvent('filter_wrong_subject', { subjectId: state.wrongSubjectFilter });
      saveState();
      return render();
    }
    if (action === 'select-reference-subject') {
      state.referenceSubject = element.dataset.referenceSubject || state.referenceSubject;
      trackEvent('select_reference_subject', { subjectId: state.referenceSubject });
      saveState();
      return render();
    }
    if (action === 'open-tool') {
      state.activeTool = element.dataset.tool || '';
      state.labStep = 0;
      state.voiceStatus = '';
      state.voiceScore = null;
      trackEvent('open_tool', { tool: state.activeTool });
      saveState();
      render();
      requestAnimationFrame(() => document.querySelector('.subject-tools')?.scrollIntoView({ behavior: 'smooth', block: 'center' }));
      return;
    }
    if (action === 'next-lab-step') {
      const lab = labCatalog[state.selectedSubject] || labCatalog.physics;
      if (state.labStep >= lab.steps.length - 1) {
        state.activeTool = '';
        state.labStep = 0;
        trackEvent('complete_lab', { subjectId: state.selectedSubject });
        return showToast('实验完成，已记录这次知识点观察');
      }
      state.labStep += 1;
      trackEvent('next_lab_step', { subjectId: state.selectedSubject, step: state.labStep });
      saveState();
      return render();
    }
    if (action === 'speak-text') {
      const text = element.dataset.speak?.trim();
      if (!text) return showToast('暂无可播放内容');
      const language = element.dataset.speakLang || 'en-US';
      const rate = Number(element.dataset.speakRate) || 0.82;
      if (globalThis.AndroidBridge?.speakText) {
        try {
          globalThis.AndroidBridge.speakText(text, language, rate);
          trackEvent('speak_text', { contentType: text.split(' ').length > 2 ? 'example' : 'word', platform: 'android' });
          return showToast(text.split(' ').length > 2 ? '正在用手机播放例句' : `正在用手机播放：${text}`);
        } catch {}
      }
      const speech = window.speechSynthesis;
      const Utterance = window.SpeechSynthesisUtterance;
      if (!speech || !Utterance) return showToast('当前浏览器暂不支持语音播放，请使用系统浏览器打开');
      const speak = () => {
        speech.cancel();
        const utterance = new Utterance(text);
        utterance.lang = language;
        utterance.rate = rate;
        const voices = speech.getVoices();
        const voice = voices.find((item) => item.lang?.toLowerCase().startsWith(utterance.lang.slice(0, 2).toLowerCase()));
        if (voice) utterance.voice = voice;
        speech.speak(utterance);
      };
      if (speech.getVoices().length) speak();
      else {
        speech.onvoiceschanged = () => {
          speech.onvoiceschanged = null;
          speak();
        };
        speak();
      }
      trackEvent('speak_text', { contentType: text.split(' ').length > 2 ? 'example' : 'word' });
      return showToast(text.split(' ').length > 2 ? '正在朗读例句，请注意连读和重音' : `正在朗读：${text}`);
    }
    if (action === 'start-voice-practice') {
      const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (!Recognition) return showToast('当前浏览器暂不支持自动跟读评分，可先使用播放范读');
      const target = 'My goal is to understand one more question today.';
      const recognition = new Recognition();
      recognition.lang = 'en-US';
      recognition.interimResults = false;
      recognition.maxAlternatives = 1;
      state.voiceStatus = '正在听你朗读，请开始说话…';
      state.voiceScore = null;
      trackEvent('start_voice_practice');
      render();
      recognition.onresult = (event) => {
        const transcript = event.results?.[0]?.[0]?.transcript || '';
        const normalize = (value) => value.toLowerCase().replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();
        const targetWords = normalize(target).split(' ');
        const spokenWords = normalize(transcript).split(' ');
        const matched = targetWords.filter((word, index) => spokenWords[index] === word).length;
        state.voiceScore = Math.round((matched / targetWords.length) * 100);
        state.voiceStatus = `识别到：${transcript}`;
        trackEvent('complete_voice_practice', { score: state.voiceScore });
        saveState();
        render();
      };
      recognition.onerror = () => {
        state.voiceStatus = '没有听清，再试一次，尽量慢一点说。';
        saveState();
        render();
      };
      try { recognition.start(); } catch { showToast('语音识别正在启动，请稍后再试'); }
      return;
    }
    if (action === 'ai-hint') {
      state.aiHintLevel = Math.max(0, Math.min(3, Number(element.dataset.level) || 0));
      saveState();
      return render();
    }
    if (action === 'review-question') {
      const targetQuestion = questions[Number(element.dataset.question)];
      const practiceQuestions = getPracticeQuestions(targetQuestion?.subjectId || subjectIdFromName(targetQuestion?.subject));
      state.selectedSubject = targetQuestion?.subjectId || state.selectedSubject;
      state.selectedQuestion = Math.max(0, practiceQuestions.findIndex((question) => question.id === targetQuestion?.id));
      state.page = 'practice';
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.questionAnswered = false;
      trackEvent('review_wrong_question', { questionId: targetQuestion?.id || 0 });
      saveState();
      return render();
    }
    if (action === 'review-all') {
      state.selectedQuestion = 0;
      state.page = 'practice';
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.questionAnswered = false;
      trackEvent('review_wrong_all');
      saveState();
      return render();
    }
    if (action === 'start-practice') {
      state.selectedSubject = element.dataset.subject || state.selectedSubject;
      state.selectedQuestion = 0;
      state.selectedAnswer = null;
      state.typedAnswer = '';
      state.questionAnswered = false;
      state.page = 'practice';
      trackEvent('start_practice', { subjectId: state.selectedSubject, source: 'practice_entry' });
      saveState();
      render();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (action === 'start-lesson') {
      state.focusKnowledgePoint = state.focusKnowledgePoint || element.dataset.lesson || '';
      state.focusCourseTitle = element.dataset.lesson || state.focusCourseTitle || state.focusKnowledgePoint;
      state.focusLessonOpen = true;
      state.page = 'learn';
      trackEvent('open_lesson', { knowledgePoint: state.focusKnowledgePoint });
      saveState();
      render();
      requestAnimationFrame(() => document.querySelector('.lesson-explanation')?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
      return;
    }
    if (action === 'go-knowledge') {
      const nextSubject = element.dataset.subject || state.selectedSubject;
      state.selectedSubject = nextSubject;
      const availableBooks = textbookOptions[nextSubject] || ['人教版'];
      if (!availableBooks.includes(state.textbook)) state.textbook = availableBooks[0];
      state.focusKnowledgePoint = element.dataset.knowledge || '';
      state.focusCourseTitle = element.dataset.course || state.focusKnowledgePoint;
      state.focusLessonOpen = false;
      state.page = 'learn';
      trackEvent('go_knowledge', { subjectId: nextSubject, hasKnowledgePoint: Boolean(state.focusKnowledgePoint) });
      saveState();
      render();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (action === 'show-report') {
      state.page = 'report';
      trackEvent('open_report');
      saveState();
      return render();
    }
    if (action === 'show-toast') return showToast(element.dataset.toast);
    if (action === 'notify') return showToast('你有 2 条学习提醒：今日任务还剩 2 项');
    if (action === 'toggle-sidebar') document.querySelector('.sidebar')?.classList.toggle('open');
    if (action === 'select-ai-mode') {
      state.aiInputMode = element.dataset.mode;
      trackEvent('select_ai_mode', { mode: state.aiInputMode });
      saveState();
      render();
      if (state.aiInputMode === 'photo') setTimeout(() => document.querySelector('#ai-image-input')?.click(), 0);
      return;
    }
    if (action === 'trigger-image-upload') return document.querySelector('#ai-image-input')?.click();
    if (action === 'remove-ai-image') {
      state.aiImageData = null;
      state.aiImageName = '';
      state.aiInputMode = 'photo';
      trackEvent('remove_ai_image');
      saveState();
      return render();
    }
    if (action === 'solve-ai') {
      const question = document.querySelector('#ai-question-input')?.value || '';
      return requestAiSolve(question, '', state.aiImageData);
    }
    if (action === 'quick-ai') {
      state.aiImageData = null;
      state.aiImageName = '';
      state.aiInputMode = 'text';
      return requestAiSolve(element.dataset.question, '', null);
    }
    if (action === 'ask-followup') {
      const followUp = document.querySelector('#ai-followup-input')?.value || '';
      if (!followUp.trim()) return showToast('写下你还不明白的地方，再来追问');
      trackEvent('ask_ai_followup', { characterCount: followUp.trim().length });
      return requestAiSolve(state.aiQuestion, followUp);
    }
    if (action === 'clear-ai') {
      state.aiResult = null;
      saveState();
      return render();
    }
    if (action === 'save-ai-error') {
      trackEvent('save_ai_error');
      return showToast('已保存到错题本，之后会推送同类验证题');
    }
  }));
  document.querySelector('#ai-image-input')?.addEventListener('change', (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) return showToast('请选择 JPG、PNG 等图片文件');
    if (file.size > 8 * 1024 * 1024) return showToast('图片不要超过 8MB，拍清楚题目即可');
    const reader = new FileReader();
    reader.onload = () => {
      state.aiImageData = reader.result;
      state.aiImageName = file.name;
      state.aiInputMode = 'photo';
      state.aiResult = null;
      trackEvent('upload_ai_image', { fileType: file.type });
      saveState();
      render();
    };
    reader.readAsDataURL(file);
  });
}

render();
trackEvent('app_open');
